Date: Sat, 21 Nov 2026 18:45:06 +0100
Subject: [PATCH] containmentitem: keep other windows from driving the menu on
 Wayland

Qt forwards pointer events from other windows to the open menu by global
position, unknown on Wayland, so hovering a settings window highlighted
menu items; drop those events and let a press there close the menu.

BUG: 504809
---
 src/plasmaquick/plasmoid/containmentitem.cpp | 67 ++++++++++++++++++++
 src/plasmaquick/plasmoid/containmentitem.h   |  1 +
 src/plasmaquick/plasmoid/plasmoiditem.cpp    |  1 +
 3 files changed, 69 insertions(+)

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..af0651b66 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -29,6 +29,7 @@
 #include <KLocalizedString>
 #include <KNotification>
 #include <KUrlMimeData>
+#include <KWindowSystem>
 #include <QDebug>
 #include <QLoggingCategory>
 #include <QMimeDatabase>
@@ -46,6 +47,64 @@
 #include <KPackage/PackageJob>
 #include <KPackage/PackageLoader>

+namespace
+{
+// While a popup is open, Qt forwards pointer events from any other window to it, mapped by global
+// position. On Wayland the position of other windows is unknown, so the menu reacted to the
+// pointer over e.g. a settings window as if it were over the menu.
+class ForeignPointerFilter : public QObject
+{
+public:
+    ForeignPointerFilter(QMenu *menu, QWindow *opener)
+        : QObject(menu)
+        , m_menu(menu)
+        , m_opener(opener)
+        , m_pointerWindow(opener)
+    {
+        qApp->installEventFilter(this);
+        connect(menu, &QMenu::aboutToHide, this, &QObject::deleteLater);
+    }
+
+    bool eventFilter(QObject *watched, QEvent *event) override
+    {
+        QWindow *window = qobject_cast<QWindow *>(watched);
+        if (!window) {
+            return false;
+        }
+        switch (event->type()) {
+        case QEvent::Enter:
+            m_pointerWindow = window;
+            break;
+        case QEvent::Leave:
+            if (m_pointerWindow == window) {
+                m_pointerWindow = nullptr;
+            }
+            break;
+        case QEvent::MouseMove:
+        case QEvent::MouseButtonPress:
+        case QEvent::MouseButtonRelease:
+        case QEvent::MouseButtonDblClick:
+            if (window->type() == Qt::Popup && m_pointerWindow && m_pointerWindow != m_opener && m_pointerWindow->type() != Qt::Popup) {
+                if (event->type() == QEvent::MouseButtonPress) {
+                    m_menu->close();
+                }
+                event->ignore();
+                return true;
+            }
+            break;
+        default:
+            break;
+        }
+        return false;
+    }
+
+private:
+    QMenu *const m_menu;
+    QPointer<QWindow> m_opener;
+    QPointer<QWindow> m_pointerWindow;
+};
+}
+
 ContainmentItem::ContainmentItem(QQuickItem *parent)
     : PlasmoidItem(parent)
     , m_wallpaperItem(nullptr)
@@ -780,6 +839,13 @@ void ContainmentItem::loadWallpaper()
     Q_EMIT wallpaperItemChanged();
 }

+void ContainmentItem::ignoreForeignPointerEvents(QMenu *menu, QWindow *opener)
+{
+    if (KWindowSystem::isPlatformWayland()) {
+        new ForeignPointerFilter(menu, opener);
+    }
+}
+
 // PROTECTED--------------------

 void ContainmentItem::mouseReleaseEvent(QMouseEvent *event)
@@ -901,6 +967,7 @@ void ContainmentItem::mousePressEvent(QMouseEvent *event)
         }
     }

+    ignoreForeignPointerEvents(m_contextMenu.get(), window());
     m_contextMenu->popup(pos);
     event->setAccepted(true);
 }
